CREATE TABLE room (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,kind VARCHAR(64) NOT NULL,target_type VARCHAR(64),target_id UUID,visibility VARCHAR(24) NOT NULL DEFAULT 'PRIVATE',status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',state_version BIGINT NOT NULL DEFAULT 0,sequence BIGINT NOT NULL DEFAULT 0,expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(status IN ('ACTIVE','LOCKED','ENDED','EXPIRED'))); CREATE INDEX idx_room_owner ON room(owner_id,created_at DESC); CREATE TABLE room_membership (id UUID PRIMARY KEY DEFAULT uuid_v7(),room_id UUID NOT NULL,principal_id UUID NOT NULL,role VARCHAR(24) NOT NULL,joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),left_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(role IN ('OWNER','MODERATOR','MEMBER','GUEST')),FOREIGN KEY(room_id) REFERENCES room(id) ON DELETE CASCADE,UNIQUE(room_id,principal_id)); CREATE INDEX idx_room_membership_active ON room_membership(room_id) WHERE left_at IS NULL;
